import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int k = fs.nextInt();

        long[] a = new long[n];
        long[] b = new long[n];
        for (int i = 0; i < n; i++) a[i] = fs.nextLong();
        for (int i = 0; i < n; i++) b[i] = fs.nextLong();

        long positiveSum = 0;
        long[] delta = new long[n];
        long maxA1 = -1, maxA2 = -1;
        int maxIdx1 = -1, maxIdx2 = -1;
        long answer = 0;

        for (int i = 0; i < n; i++) {
            long gain = a[i] - b[i];
            if (gain >= 0) positiveSum += gain;
            delta[i] = gain >= 0 ? b[i] : a[i];

            if (a[i] > maxA1) {
                maxA2 = maxA1;
                maxIdx2 = maxIdx1;
                maxA1 = a[i];
                maxIdx1 = i;
            } else if (a[i] > maxA2) {
                maxA2 = a[i];
                maxIdx2 = i;
            }

            answer = Math.max(answer, a[i]);
        }

        Arrays.sort(delta);
        int freeCount = Math.min(k, n - 1);
        long topDeltaSum = 0;
        for (int i = n - freeCount; i < n; i++) {
            if (i >= 0) topDeltaSum += delta[i];
        }

        long threshold = freeCount > 0 ? delta[n - freeCount] : Long.MAX_VALUE;
        long replacement = freeCount > 0 ? delta[n - freeCount - 1] : 0;

        for (int i = 0; i < n; i++) {
            long gain = a[i] - b[i];
            long base = a[i] + positiveSum - Math.max(0L, gain);
            long freeBonus = topDeltaSum;

            if (freeCount > 0 && delta[i] >= threshold) {
                freeBonus = topDeltaSum - delta[i] + replacement;
            }

            answer = Math.max(answer, base + freeBonus);

            if (gain < 0 && n > 1) {
                long loss = -gain;
                long terminalA = maxIdx1 != i ? maxA1 : maxA2;
                if (terminalA >= loss) {
                    answer = Math.max(answer, terminalA - loss);
                }
            }
        }

        System.out.println(answer);
    }
}
